head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil21104";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.type

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil21104.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SubmitAgree_onclick
 * @description btn_SubmitAgree 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_SubmitAgree_onclick = async function(e){
    try {
        await scwin.submitAgree()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21104.btn_SubmitAgree_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil21104.btn_window_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name submitAgree
 * @description submit Agree 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitAgree = async function () {
    const obj = $c.util.getComponent('rd_agreeYn');
    let checkedVal = "";
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].checked === true) {
            checkedVal = obj[i].value;
            break;
        }
    }
    if ("N" === checkedVal) {
        await $c.win.alert("동의함에 체크하셔야 제출하실 수 있습니다.");
        obj.focus();
        return false;
    }
    let origWin = (($c.win.getOpenerScope() || {}).scwin || null);
    try {
        origWin = (($c.win.getOpenerScope() || {}).scwin || null);
        if (origWin != null) {
            origWin.fn_Submit((String(((dma_pageContext.get("type") ?? "")) == null ? '' : ((dma_pageContext.get("type") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("type") ?? "")) == null ? '' : ((dma_pageContext.get("type") ?? "")))));
        } else {
            await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. 다시 시도해주십시요");
        }
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil21104' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. 다시 시도해주십시요\n\n" + e);
    }
    $c.win.closePopup();
};
